// Participant-level, paired analyses. No trial is treated as an independent person.
export const ANALYSIS_VERSION='paired-v2-2026-11-03';
const finite=x=>typeof x==='number'&&Number.isFinite(x);
export const mean=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:null;
export function sd(a){const m=mean(a);return a.length>1?Math.sqrt(a.reduce((s,x)=>s+(x-m)**2,0)/(a.length-1)):null;}
function logGamma(z){const c=[676.5203681218851,-1259.1392167224028,771.32342877765313,-176.6150291621406,12.507343278686905,-.13857109526572012,9.9843695780195716e-6,1.5056327351493116e-7];if(z<.5)return Math.log(Math.PI)-Math.log(Math.sin(Math.PI*z))-logGamma(1-z);z--;let x=.99999999999980993;for(let i=0;i<c.length;i++)x+=c[i]/(z+i+1);const t=z+7.5;return .5*Math.log(2*Math.PI)+(z+.5)*Math.log(t)-t+Math.log(x);}
function betaCF(a,b,x){let c=1,d=1-(a+b)*x/(a+1);if(Math.abs(d)<1e-30)d=1e-30;d=1/d;let h=d;for(let m=1;m<=250;m++){let aa=m*(b-m)*x/((a+2*m-1)*(a+2*m));d=1+aa*d;if(Math.abs(d)<1e-30)d=1e-30;c=1+aa/c;if(Math.abs(c)<1e-30)c=1e-30;d=1/d;h*=d*c;aa=-(a+m)*(a+b+m)*x/((a+2*m)*(a+2*m+1));d=1+aa*d;if(Math.abs(d)<1e-30)d=1e-30;c=1+aa/c;if(Math.abs(c)<1e-30)c=1e-30;d=1/d;const delta=d*c;h*=delta;if(Math.abs(delta-1)<3e-14)break;}return h;}
function beta(x,a,b){if(x<=0)return 0;if(x>=1)return 1;const bt=Math.exp(logGamma(a+b)-logGamma(a)-logGamma(b)+a*Math.log(x)+b*Math.log1p(-x));return x<(a+1)/(a+b+2)?bt*betaCF(a,b,x)/a:1-bt*betaCF(b,a,1-x)/b;}
export function tP(t,df){return Math.min(1,Math.max(0,beta(df/(df+t*t),df/2,.5)));}
export function tCritical(df){let lo=0,hi=1;while(tP(hi,df)>.05)hi*=2;for(let i=0;i<90;i++){const m=(lo+hi)/2;if(tP(m,df)>.05)lo=m;else hi=m;}return (lo+hi)/2;}
export function signTest(d){const nonzero=d.filter(x=>Math.abs(x)>1e-12),n=nonzero.length;if(!n)return {n:0,p:1};const k=Math.min(nonzero.filter(x=>x>0).length,nonzero.filter(x=>x<0).length);let p=0;for(let i=0;i<=k;i++)p+=Math.exp(logGamma(n+1)-logGamma(i+1)-logGamma(n-i+1)-n*Math.log(2));return {n,p:Math.min(1,2*p)};}
export function paired(values){const d=values.filter(finite),n=d.length,m=mean(d),s=sd(d),result={n,mean:m,sd:s,df:n-1,ci:null,t:null,p:null,dz:null,sign:null,status:'至少需要 5 名完整配对被试'};if(n<5)return result;if(s<1e-12)return {...result,status:'差值零方差，无法可靠计算 t 检验或标准化效应量'};const se=s/Math.sqrt(n),crit=tCritical(n-1),t=m/se;return {...result,ci:[m-crit*se,m+crit*se],t,p:tP(t,n-1),dz:m/s,sign:signTest(d),status:'可计算；小样本须检查差值分布'};}
export function holm(ps){const r=ps.map(()=>null),a=ps.map((p,i)=>({p,i})).filter(x=>finite(x.p)).sort((a,b)=>a.p-b.p);let last=0;for(let k=0;k<a.length;k++){last=Math.max(last,Math.min(1,a[k].p*(a.length-k)));r[a[k].i]=last;}return r;}

function parsed(v){if(typeof v!=='string')return v;try{return JSON.parse(v);}catch{return null;}}
function experimentId(id){return ['drive','map','rotate'].find(x=>id===x||new RegExp('^starparcel_'+x+'_v[1-9]$').test(id));}
export function normalize(input){const root=parsed(input),list=Array.isArray(root)?root:root?.records??root?.sessions??(root?.trials?[root]:null);if(!Array.isArray(list))throw Error('请导入本程序的完整 JSON，或课程接口 records JSON；CSV 不包含完整协议，不在这里自动推断。');const good=[],errors=[];for(const [i,raw] of list.entries()){const experiment=experimentId(raw?.experiment),meta=parsed(raw?.meta)||{},rows=parsed(raw?.trials);if(!experiment||!Array.isArray(rows)||!rows.length){errors.push('记录 '+(i+1)+'：不是本程序的完整试次记录');continue;}const first=rows[0]||{},tier=raw.tier||meta.tier||first.tier||raw.condition,protocol=raw.protocol||meta.protocol||first.protocol,participant=String(raw.participant||'').trim();if(!participant||!['quick','medium','full'].includes(tier)||!protocol||rows.some(t=>!t||!Number.isInteger(t.cond)||t.cond<0||t.cond>(experiment==='map'?2:1)||![0,1].includes(t.correct)||!(t.rt===null||t.rt===undefined||finite(t.rt))||finite(t.rt)&&t.rt<0)){errors.push('记录 '+(i+1)+'：缺少编号、档位、协议或合法试次字段');continue;}const cameraEvidence=rows.some(t=>finite(t.calibration_error)&&finite(t.gaze_samples)&&t.gaze_samples>0);const mode=raw.mode||first.mode||(['formal','pilot'].includes(meta.record_class)?'formal':cameraEvidence?'camera-evidence':null),eligible=raw.courseEligible??meta.course_eligible??first.courseEligible??false,id=String(raw.id||meta.session_id||first.session_id||raw.record_id||[experiment,participant,protocol,tier,raw.created||raw.created_at||JSON.stringify(rows)].join('|'));good.push({id,experiment,participant,tier,protocol,mode,courseEligible:eligible===true,created:raw.created||raw.created_at||'',collectionPolicy:raw.collectionPolicy||meta.collection_policy||first.collectionPolicy||'legacy-policy',calibration:raw.calibration||{meanError:meta.calibration_error??first.calibration_error,qualityPass:meta.calibration_quality_flag??first.calibration_quality_flag},trials:rows.map(t=>({...t,rt:t.rt_missing||t.rt===undefined?null:t.rt,aoi:parsed(t.aoi)||parsed(t.aoi_summary)||{}}))});}if(!good.length&&errors.length)throw Error(errors.slice(0,3).join('；'));return {sessions:good,errors};}
export function signature(s){return [s.experiment,s.protocol,s.tier,s.collectionPolicy||'legacy-policy'].join(' | ');}
// Descriptive paper comparisons can use a completed short camera session.
// Keep this selection separate from the full-cell gate for inferential tests.
export function descriptiveSessions(input,key){const people=new Map();for(const s of input){if(!['formal','camera-evidence'].includes(s.mode)||signature(s)!==key)continue;const old=people.get(s.participant);if(!old||(s.created||s.id)<(old.created||old.id))people.set(s.participant,s);}return [...people.values()];}
function valid(s){return s.trials.filter(t=>!t.invalid);}
function cellKey(e,t){if(e==='drive')return [t.priority,t.cond,t.event].join('/');if(e==='map')return [t.cond,t.relative].join('/');return [t.cond,t.angle,t.mirror===true||t.mirror===1?'mirror':'same'].join('/');}
export function cells(s){const keys=[];if(s.experiment==='drive')for(const p of ['road','panel'])for(const c of [0,1])for(const e of ['road','panel','speed','oncoming'])keys.push([p,c,e].join('/'));else if(s.experiment==='map')for(const c of [0,1,2])for(const d of [0,90,180,270])keys.push([c,d].join('/'));else for(const c of [0,1])for(const a of [0,60,120])for(const m of ['same','mirror'])keys.push([c,a,m].join('/'));const counts=Object.fromEntries(keys.map(k=>[k,0]));for(const t of valid(s)){const k=cellKey(s.experiment,t);if(k in counts)counts[k]++;}const min=Math.min(...Object.values(counts));return {min,counts,complete:min>=10};}
export function selectSessions(input,key){const rows=input.filter(s=>signature(s)===key),unique=new Map(),excluded={demo:0,incomplete:0,duplicate:0};for(const s of rows){if(s.mode!=='formal'||s.tier!=='full'||!s.courseEligible){excluded.demo++;continue;}if(!cells(s).complete){excluded.incomplete++;continue;}const prev=unique.get(s.participant);if(prev){excluded.duplicate++;if((s.created||s.id)<(prev.created||prev.id))unique.set(s.participant,s);}else unique.set(s.participant,s);}return {sessions:[...unique.values()].sort((a,b)=>a.participant.localeCompare(b.participant)),excluded,total:rows.length};}
function rt(rows){return mean(rows.filter(t=>t.correct===1&&!t.anticipatory&&finite(t.rt)&&t.rt>=150).map(t=>t.rt));}
function acc(rows){return rows.length?100*rows.filter(t=>t.correct===1).length/rows.length:null;}
function balanced(s,metric,cond,subset=()=>true){const groups=new Map();for(const t of valid(s).filter(t=>t.cond===cond&&subset(t))){const k=cellKey(s.experiment,{...t,cond:0});if(!groups.has(k))groups.set(k,[]);groups.get(k).push(t);}const expected=s.experiment==='drive'?(s.protocol?.startsWith('starparcel-v4')?4:6):s.experiment==='map'?4:3;if(groups.size!==expected)return null;const a=[...groups.values()].map(metric);return a.some(v=>!finite(v))?null:mean(a);}
function rotationSlope(s,cond){const points=[0,60,120].map(angle=>({x:angle,y:rt(valid(s).filter(t=>t.cond===cond&&!t.mirror&&t.angle===angle))}));if(points.some(p=>!finite(p.y)))return null;const y=mean(points.map(p=>p.y));return points.reduce((a,p)=>a+(p.x-60)*(p.y-y),0)/7200;}
function roadShare(s,priority){let road=0,panel=0;for(const t of valid(s).filter(t=>t.priority===priority)){road+=(t.aoi?.road||0)+(t.aoi?.road_instrument||0);panel+=t.aoi?.cargo_instrument||0;}return road+panel?100*road/(road+panel):null;}
const sub=(a,b)=>finite(a)&&finite(b)?a-b:null;
export const contrasts={
 drive:[{id:'cue_rt',label:'显著提示 − 常规：正确 RT',unit:'ms',direction:-1,kind:'改进',value:s=>sub(balanced(s,rt,1,t=>s.protocol?.startsWith('starparcel-v4')?['panel','speed'].includes(t.event):t.event!=='oncoming'),balanced(s,rt,0,t=>s.protocol?.startsWith('starparcel-v4')?['panel','speed'].includes(t.event):t.event!=='oncoming'))},{id:'cue_acc',label:'显著提示 − 常规：正确率',unit:'百分点',direction:1,kind:'改进',value:s=>sub(balanced(s,acc,1,t=>s.protocol?.startsWith('starparcel-v4')?['panel','speed'].includes(t.event):t.event!=='oncoming'),balanced(s,acc,0,t=>s.protocol?.startsWith('starparcel-v4')?['panel','speed'].includes(t.event):t.event!=='oncoming'))},{id:'priority_gaze',label:'道路优先 − 仪表优先：道路采样占比',unit:'百分点',direction:1,kind:'原文方向',value:s=>sub(roadShare(s,'road'),roadShare(s,'panel'))}],
 map:[{id:'heading_rt',label:'航向向上 − 北向上：正确 RT',unit:'ms',direction:-1,kind:'原文方向',value:s=>sub(balanced(s,rt,1),balanced(s,rt,0))},{id:'sector_rt',label:'自适应扇形 − 北向上：正确 RT',unit:'ms',direction:-1,kind:'改进',value:s=>sub(balanced(s,rt,2),balanced(s,rt,0))},{id:'sector_acc',label:'视野扇形 − 北向上：正确率',unit:'百分点',direction:1,kind:'改进',value:s=>sub(balanced(s,acc,2),balanced(s,acc,0))}],
 rotate:[{id:'baseline_slope',label:'无参照框：同形 RT–角度斜率',unit:'ms/°',direction:1,kind:'原文方向',value:s=>rotationSlope(s,0)},{id:'axis_rt',label:'有参照框 − 无坐标轴：同形正确 RT',unit:'ms',direction:-1,kind:'改进',value:s=>sub(balanced(s,rt,1,t=>!t.mirror),balanced(s,rt,0,t=>!t.mirror))},{id:'axis_acc',label:'有坐标轴 − 无坐标轴：全部试次正确率',unit:'百分点',direction:1,kind:'改进',value:s=>{const a=valid(s);return sub(acc(a.filter(t=>t.cond===1)),acc(a.filter(t=>t.cond===0)));}},{id:'axis_slope',label:'有坐标轴 − 无坐标轴：同形斜率',unit:'ms/°',direction:-1,kind:'探索',value:s=>sub(rotationSlope(s,1),rotationSlope(s,0))}]
};
export function analyze(input,key){const selected=selectSessions(input,key),experiment=key.split(' | ')[0];if(!contrasts[experiment])throw Error('未知实验');const results=contrasts[experiment].map(def=>{const observations=selected.sessions.map(s=>({participant:s.participant,value:def.value(s)})),values=observations.map(o=>o.value),stat=paired(values);return {...def,...stat,value:undefined,missing:observations.filter(o=>!finite(o.value)).map(o=>o.participant),observations};});const adjusted=holm(results.map(r=>r.p));results.forEach((r,i)=>{r.pHolm=adjusted[i];r.conclusion=!finite(r.pHolm)?'证据不足':r.pHolm<.05?(r.mean*r.direction>0?'支持预测方向':'显著差异与预测方向相反'):'证据不足，不能据此声称没有效应';});return {version:ANALYSIS_VERSION,key,...selected,results,quality:selected.sessions.map(s=>({participant:s.participant,minCell:cells(s).min,error:s.calibration?.meanError??null,qualityPass:s.calibration?.qualityPass??null}))};}
export const references={
 drive:{title:'Horrey, Wickens & Consalus (2006)',url:'https://doi.org/10.1037/1076-898X.12.2.67',finding:'模拟驾驶实验中，任务优先级显著影响视觉扫描；SEEV 用于预测扫描分配。',ours:'比较道路优先与仪表优先时的道路采样占比，检查价值操纵的方向；显著性告警属于本项目新增比较。',limit:'原文包含驾驶和车内任务、带宽/复杂性等操纵；本项目是离散火箭告警，不测连续车辆控制，不进行完整 SEEV 拟合。',metric:'priority_gaze',evidence:'原文摘要；Journal of Experimental Psychology: Applied 12, 67–78。'},
 map:{title:'Aretz (1991)',url:'https://doi.org/10.1177/001872089103300107',finding:'航向向上便于匹配自我中心前方视野；北向上有利于稳定的认知地图；视觉动量设计试图兼顾两者。',ours:'用航向向上与北向上的相对方向判断 RT 差检查方向；新增北向上视野扇形与普通北向上比较。',limit:'只测即时方向判断，没有环境学习测验；本项目视野扇形不是原文视觉动量显示的完整复制。',metric:'heading_rt',evidence:'原文摘要；Human Factors 33, 85–101。'},
 rotate:{title:'Shepard & Metzler (1971)',url:'https://doi.org/10.1126/science.171.3972.701',finding:'同形判断的反应时随角度差近似线性增加；原文分别考察画面内与深度旋转。',ours:'在无坐标轴同形试次中计算 0°/60°/120° 的 RT–角度斜率，新增坐标轴条件检验 RT 与斜率变化。',limit:'形状、角度范围、渲染、按键与设备均有变化；未对比两类旋转轴，不声称精确复现原文速度。',metric:'baseline_slope',evidence:'原文摘要及第 703 页；Science 171, 701–703。'}
};
